import {createHash} from 'node:crypto';
import {mockMapTools,mapDataset} from './nextjs-map.mjs';
import {atlasBeaches} from './nextjs-atlas.mjs';
import {postsModule,tripId} from './nextjs-posts.mjs';
export const placeBeaches=structuredClone(atlasBeaches);for(const beach of placeBeaches.beaches)Object.assign(beach,{detail_file:'data/example-place.json',jurisdiction_id:'unverified',requirements:'Check the signed access information.',booking_url:'https://example.invalid/book',source_url:'https://example.invalid/location',reference_label:'Listed beach reference',facts:[{label:'Access',text:'Public stairs at the northern end.',source_url:'https://example.invalid/access',reviewed_at:'2026-10-30'}],restrictions:[{activity:'spearfishing',text:'Check the current marine zoning.',source_url:'https://example.invalid/zoning',reviewed_at:'2026-10-30'}],access_points:[{name:'Northern steps',point:beach.point,mode:'entry',source_url:'https://example.invalid/entry'}],depth_evidence:[{depth_m:12,kind:'operator report',reference:'Operator briefing',source_url:'https://example.invalid/depth'}]});
export const stays=Array.from({length:35},(_,i)=>({id:'stay-'+i,name:i===0?'Coastal Camp':i===1?'Unverified Cove':'Stay '+String(i).padStart(2,'0'),point:[145+i*.001,-38],types:i%3===0?['campground']:i%3===1?['cabin']:['caravan-park'],verified:i!==1,reviewed_at:'2026-10-30',amenities:{toilets:i%2===0,showers:i%3===0,power:i%5===0},operator_url:i===1?null:'https://example.invalid/operator/'+i,source_url:'https://example.invalid/stay/'+i,location_source_url:'https://example.invalid/map/'+i,amenities_source_url:'https://example.invalid/amenities/'+i,vehicle_access:'Check with operator',season:'Seasonal access',status:'Confirm current availability.'}));
export const detail={beaches:placeBeaches.beaches,stays,surveys:Array.from({length:35},(_,i)=>({name:'Survey '+i,metadata_url:'https://example.invalid/survey/'+i,survey_end:'2020',licence:'CC BY 4.0',download_url:'https://example.invalid/download/'+i}))};
export const social={posts:[{url:'https://www.instagram.com/p/curated/',title:'Sourced coast view',location_context:'Bondi reference location.',author:'Coastal creator',reviewed_at:'2026-10-30',association_source:'https://example.invalid/association',beach_ids:['bondi']},{url:'https://x.com/coast/status/1234567890123456789',title:'Coast update',location_context:'A historical coastal image.',author:'Coast observer',reviewed_at:'2026-10-30',beach_ids:['bondi']}]};
export const discovered={id:'discovered-public',url:'https://www.instagram.com/p/discoveredpublic/',title:'Shared coastal moment',author:'public.diver',discovered:true,posted_at:'2026-10-30T00:00:00Z'};
export const trips=[{id:tripId,title:'Reef week',beachName:'Bondi Beach',start:'2026-10-30',end:'2026-10-31',total:{dives:2},authorName:'Alice'}];
export const approved={id:'approved-one',url:'https://www.instagram.com/p/approvedone/',platform:'instagram',creator_handle:'alice.dives',beach_id:'bondi'};
const people=[{id:'maya',displayName:'Maya',regular:true,bio:'A familiar face at the coast.',reasons:['Shared spot'],participationPoints:42,instagram:'https://www.instagram.com/maya.dives/',connection:'accepted'},{id:'kai',displayName:'Kai',regular:false,bio:'Looking for a dive buddy.',reasons:['Recently checked in'],connection:null}];
const actions=`if(action==='mediaInbox')return {instagram:{connected:false,collecting:false,ownerVerified:false},items:[],limit:100};if(action==='community'){if(window.delayPlaceCommunity){window.delayPlaceCommunity=false;await new Promise(resolve=>window.releasePlaceCommunity=resolve);}return {ownVisits:window.placeVisitCount||2,people:(value.cursor?[{id:'bob',displayName:'Bob',regular:false,bio:'A visitor on the next page.',reasons:['Shared spot']}]:${JSON.stringify(people)}).filter(p=>!(window.placeBlocked||[]).includes(p.id)),cursor:!value.cursor&&sessionStorage.getItem('fixture:place-pages')?'next-folk':null};}if(action==='stats')return value.target==='kai'?{level:0,progress:2,sharingClosed:true,stats:{}}:{level:2,progress:8,stats:{visits:8,dives:10,minutes:60,typicalDepth:12}};if(action==='checkin'){window.placeVisitCount=3;return {count:3};}if(action==='posts')return {enabled:true,posts:[value.cursor?{...${JSON.stringify(approved)},id:'approved-two',url:'https://www.instagram.com/p/approvedtwo/'}:${JSON.stringify(approved)}],cursor:value.cursor?null:'more-posts'};if(action==='report'||action==='reportPost')return {};if(action==='block'){(window.placeBlocked||=[]).push(value.target);return {};}`;
export const placeModule=postsModule.replace("window.accountCalls.push({action,value});", "window.accountCalls.push({action,value});"+actions)+`\napi.ensureProfile=async()=>{};api.list=async()=>({sessions:[],more:false,cursor:null});api.profile=async()=>({displayName:'Alice'});api.instagramPosts=async()=>[{url:'https://www.instagram.com/p/sharedcommunity/',title:'Community image',location_context:'Shared by the creator.',author:'alice.dives',community:true}];\n`;
export async function mockPlace(page,base){await mockMapTools(page,base);const bodies={'beaches.json':placeBeaches,'data/example-place.json':detail,'data/beach-summaries.json':{beaches:placeBeaches.beaches.map(b=>({id:b.id,start_label:'Listed beach reference',datum:'AHD',survey_date:'2020',depths:Object.fromEntries([5,10,15,20].map(d=>[d,{distance_m:d*10}]))}))},'social.json':social,'guides.json':{jurisdictions:{EXT:[{label:'Marine authority',url:'https://example.invalid/authority'}]}}},files={...mapDataset.files,...Object.fromEntries(Object.entries(bodies).map(([path,value])=>{const body=JSON.stringify(value);return [path,{hash:createHash('sha256').update(body).digest('hex'),bytes:Buffer.byteLength(body),label:path}];}))};await page.route('**/neon-client.js',r=>r.fulfill({contentType:'text/javascript',body:placeModule}));for(const [path,json]of Object.entries(bodies))await page.route('**/'+path+'*',r=>r.fulfill({json}));await page.route('**/v1/sites/catalog*',r=>r.fulfill({json:placeBeaches}));await page.route('**/sites-snapshot.json*',r=>r.fulfill({json:placeBeaches}));await page.route('**/data/downloads.json*',r=>r.fulfill({json:{version:1,revision:'place',files,regions:{}}}));await page.route('**/instagram/posts*',r=>{const u=new URL(r.request().url());return r.fulfill({json:{posts:u.searchParams.get('cursor')?[{...discovered,id:'second-discovered',url:'https://www.instagram.com/p/secondpublic/',title:'Second public image'}]:[discovered],cursor:u.searchParams.get('cursor')?null:'next-photos'}})});await page.route('**/instagram/posts/*/report',r=>r.fulfill({json:{ok:true}}));await page.route('**/trips?*',r=>r.fulfill({json:{trips}}));await page.route('**/community/posts?*',r=>r.fulfill({json:{enabled:true,posts:[approved],cursor:null}}));await page.route('**/community/referral',r=>r.fulfill({json:{ok:true}}));}
